ee:message.ee:set-payload:
%dw 2.0
                    output application/json
                    ---
                    {
                        errorCode: "INVALID_REQUEST_PAYLOAD",
                        errorMessage: error.description default "Bad Request",
                        correlationId: vars.correlationId default correlationId,
                        timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"}
                    }

%dw 2.0
                    output application/json
                    ---
                    {
                        errorCode: "RESOURCE_NOT_FOUND",
                        errorMessage: "The requested API endpoint was not found.",
                        correlationId: vars.correlationId default correlationId,
                        timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"}
                    }

%dw 2.0
                    output application/json
                    ---
                    {
                        errorCode: "DATABASE_UNAVAILABLE",
                        errorMessage: "Transient database failure. Please retry shortly.",
                        correlationId: vars.correlationId default correlationId,
                        timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"}
                    }

%dw 2.0
                    output application/json
                    ---
                    {
                        errorCode: "DOWNSTREAM_TIMEOUT",
                        errorMessage: "Timeout communicating with downstream system service.",
                        correlationId: vars.correlationId default correlationId,
                        timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"}
                    }

%dw 2.0
                    output application/json
                    ---
                    {
                        errorCode: "INTERNAL_SERVER_ERROR",
                        errorMessage: error.description default "An unexpected error occurred during execution.",
                        correlationId: vars.correlationId default correlationId,
                        timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"}
                    }
